import { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function LoginForm({ setIsAuthenticated }) {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [errors, setErrors] = useState({});
  const [message, setMessage] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setErrors({});
    setMessage('');

    try {
      const response = await fetch('http://127.0.0.1:8000/api/login', {
        method: 'POST',
        credentials: 'include', // Для передачи кук
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
          'X-Requested-With': 'XMLHttpRequest' // Добавляем для Laravel
        },
        body: JSON.stringify({
          email: formData.email,
          password: formData.password
        })
      });

      // Проверяем статус ответа перед парсингом JSON
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        if (response.status === 422) {
          setErrors(errorData.errors || {});
          throw new Error('Проверьте правильность введенных данных');
        }
        throw new Error(errorData.message || 'Ошибка авторизации');
      }

      const data = await response.json();

      // Сохраняем токен и статус аутентификации
      localStorage.setItem('authToken', data.token);
      setIsAuthenticated(true);

      // Перенаправляем с заменой истории
      navigate('/dashboard', { replace: true });

    } catch (error) {
      setMessage(error.message || 'Произошла ошибка при входе');
      console.error('Login error:', error);

      // Логируем полный объект ошибки для отладки
      if (error.response) {
        console.error('Response error:', await error.response.json());
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Очищаем ошибку при изменении поля
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }));
    }
  };

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div className="form-group">
        <label htmlFor="email">Email:</label>
        <input
          id="email"
          type="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          required
          autoComplete="username"
          aria-describedby="emailError"
          className={errors?.email ? 'is-invalid' : ''}
        />
        {errors?.email && (
          <div id="emailError" className="error-message">
            {errors.email[0]}
          </div>
        )}
      </div>

      <div className="form-group">
        <label htmlFor="password">Пароль:</label>
        <input
          id="password"
          type="password"
          name="password"
          value={formData.password}
          onChange={handleChange}
          required
          autoComplete="current-password"
          aria-describedby="passwordError"
          className={errors?.password ? 'is-invalid' : ''}
        />
        {errors?.password && (
          <div id="passwordError" className="error-message">
            {errors.password[0]}
          </div>
        )}
      </div>

      <button 
        type="submit" 
        disabled={isLoading}
        aria-busy={isLoading}
        className="submit-button"
      >
        {isLoading ? (
          <>
            <span className="spinner" aria-hidden="true"></span>
            <span>Вход...</span>
          </>
        ) : 'Войти'}
      </button>

      {message && (
        <div 
          className={`status-message ${errors ? 'error' : 'success'}`}
          role="alert"
        >
          {message}
        </div>
      )}
    </form>
  );
}

export default LoginForm;
